import{_ as e,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"45Drives at Cephalocon 2025- A Recap Vlog for the Ceph Community","description":"","frontmatter":{"title":"45Drives at Cephalocon 2025- A Recap Vlog for the Ceph Community","date":"2025-11-14T00:00:00.000Z","updated":"2025-11-15T00:00:00.000Z","tags":["Ceph","Cephlacon","Distributed Storage","Open Source Community","Storage Solutions"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/45Drives_at_Cephalocon_2025_-_A_Recap_Vlog_for_the_Ceph_Community.md","filePath":"posts/2025/45Drives_at_Cephalocon_2025_-_A_Recap_Vlog_for_the_Ceph_Community.md","lastUpdated":1780459816000}'),a={name:"posts/2025/45Drives_at_Cephalocon_2025_-_A_Recap_Vlog_for_the_Ceph_Community.md"};function i(n,t,d,h,s,p){return l(),o("div",null,[...t[0]||(t[0]=[r('<h3 id="cephlacon-2025-vancouver-会议纪要" tabindex="-1">Cephlacon 2025 Vancouver 会议纪要 <a class="header-anchor" href="#cephlacon-2025-vancouver-会议纪要" aria-label="Permalink to &quot;Cephlacon 2025 Vancouver 会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>会议名称</strong>: Cephlacon 2025</li><li><strong>地点</strong>: 加拿大温哥华会议中心 (Vancouver Convention Center)</li><li><strong>主办方</strong>: Ceph Foundation</li><li><strong>主要参与者</strong>: <ul><li>Brett Kelly（45 Drives技术总监）</li><li>Ceph社区成员、赞助商代表及开发者</li></ul></li></ul><h4 id="会议关键讨论内容" tabindex="-1">会议关键讨论内容 <a class="header-anchor" href="#会议关键讨论内容" aria-label="Permalink to &quot;会议关键讨论内容&quot;">​</a></h4><ol><li><p><strong>活动背景与赞助情况</strong></p><ul><li>45 Drives作为白金赞助商首次参加Cephlacon，表示对加拿大主场的支持。</li><li>强调了社区活动组织、硬件厂商合作等对Ceph生态的贡献。</li></ul></li><li><p><strong>Ceph社区贡献与生态合作</strong></p><ul><li>Brett Kelly分享了45 Drives如何通过YouTube普及Ceph技术，吸引更多用户。</li><li>呼吁存储厂商加入Ceph Foundation，共同优化存储解决方案。</li></ul></li><li><p><strong>技术展示与反馈</strong></p><ul><li>45 Drives展示了基于Ceph的存储服务器硬件，供社区成员评估和反馈。</li><li>讨论了CRUSH算法优化、BlueStore和RocksDB性能调优、多云环境下Ceph的hybrid cloud集成等话题。</li></ul></li><li><p><strong>Ceph Foundation动态</strong></p><ul><li>讨论了基金会预算分配及资金使用情况，强调推动Ceph在分布式存储领域的标准化和生态扩展。</li></ul></li><li><p><strong>社交与社区建设</strong></p><ul><li>活动包括赞助商展示、技术演讲、交流晚宴等环节，促进开发者与用户间的沟通。</li><li>强调线下活动对开源社区凝聚力的重要性。</li></ul></li></ol><h4 id="决议与行动计划" tabindex="-1">决议与行动计划 <a class="header-anchor" href="#决议与行动计划" aria-label="Permalink to &quot;决议与行动计划&quot;">​</a></h4><ol><li><p><strong>技术合作</strong></p><ul><li>45 Drives将继续通过硬件展示和内容输出降低Ceph的学习门槛。</li><li>推动更多存储厂商加入Ceph生态，共同优化erasure coding和replication策略。</li></ul></li><li><p><strong>社区扩展</strong></p><ul><li>计划在2026年Cephlacon中增加更多hands-on workshop。</li><li>探索在纽芬兰举办区域性Ceph活动的可能性。</li></ul></li><li><p><strong>基金会工作</strong></p><ul><li>加强预算透明度，定期发布资金使用报告。</li><li>推动 Kubernetes 和 Ceph 的深度集成。</li></ul></li></ol><h4 id="后续重点任务" tabindex="-1">后续重点任务 <a class="header-anchor" href="#后续重点任务" aria-label="Permalink to &quot;后续重点任务&quot;">​</a></h4><ul><li>45 Drives将整理硬件反馈并优化产品设计，制作技术回顾视频。</li><li>Ceph Foundation将公布2025年预算细节及技术路线图，筹备2026年会议选址。</li></ul><h4 id="保留的关键术语-中英对照" tabindex="-1">保留的关键术语（中英对照） <a class="header-anchor" href="#保留的关键术语-中英对照" aria-label="Permalink to &quot;保留的关键术语（中英对照）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>英文术语</th><th>中文对照</th></tr></thead><tbody><tr><td>CRUSH algorithm</td><td>CRUSH算法</td></tr><tr><td>OSD / MON / MDS</td><td>存储守护进程 / 监控节点 / 元数据服务器</td></tr><tr><td>RADOS / librados</td><td>可靠分布式对象存储 / 客户端库</td></tr><tr><td>erasure coding</td><td>纠删码</td></tr><tr><td>hybrid cloud</td><td>混合云</td></tr><tr><td>hands-on workshop</td><td>实操工作坊</td></tr><tr><td>Kubernetes</td><td>Kubernetes</td></tr><tr><td>CephFS</td><td>Ceph 文件系统</td></tr><tr><td>RBD</td><td>块设备</td></tr><tr><td>Cephlacon</td><td>Cephlacon (此处为音译，实际应为Cephalocon)</td></tr></tbody></table>',11)])])}const c=e(a,[["render",i]]);export{_ as __pageData,c as default};
